<?php

namespace App\Services\Pks\Template;

use App\Models\Leads;
use App\Models\Company;
use App\Models\Kebutuhan;
use App\Models\RuleThr;
use App\Models\SalaryRule;
use App\Models\Pks;
use App\Services\Pks\Template\Concerns\FillsPksTemplateData;

/**
 * Pure HTML rendering for the fallback PKS agreement template.
 * All placeholders are filled from the available data objects.
 * Designed to be composed by PksPerjanjianTemplateService.
 */
class PksTemplateRenderer
{
    use FillsPksTemplateData;

    public function __construct(
        public Leads $leads,
        public Company $company,
        public Kebutuhan $kebutuhan,
        public RuleThr $ruleThr,
        public SalaryRule $salaryRule,
        public string $pksNomor,
        public ?Pks $pks = null,
        public $persentase = null,
    ) {}

    public function generateAllSections(): array
    {
        return [
            ['pasal' => 'Pembukaan', 'judul' => 'Pembukaan', 'raw_text' => $this->generatePembukaan()],
            ['pasal' => 'Pasal 1', 'judul' => 'RUANG LINGKUP PEKERJAAN', 'raw_text' => $this->generatePasal1()],
            ['pasal' => 'Pasal 2', 'judul' => 'HAK & KEWAJIBAN PARA PIHAK', 'raw_text' => $this->generatePasal2()],
            ['pasal' => 'Pasal 3', 'judul' => 'TUNJANGAN HARI RAYA', 'raw_text' => $this->generatePasal3()],
            ['pasal' => 'Pasal 4', 'judul' => 'BIAYA DAN PEMBAYARAN', 'raw_text' => $this->generatePasal4()],
            ['pasal' => 'Pasal 5', 'judul' => 'JAMINAN PIHAK KEDUA', 'raw_text' => $this->generatePasal5()],
            ['pasal' => 'Pasal 6', 'judul' => 'FORCE MAJEURE', 'raw_text' => $this->generatePasal6()],
            ['pasal' => 'Pasal 7', 'judul' => 'JANGKA WAKTU PERJANJIAN', 'raw_text' => $this->generatePasal7()],
            ['pasal' => 'Pasal 8', 'judul' => 'PENYELESAIAN PERSELISIHAN', 'raw_text' => $this->generatePasal8()],
            ['pasal' => 'Pasal 9', 'judul' => 'PENUTUP', 'raw_text' => $this->generatePasal9()],
            ['pasal' => 'LAMPIRAN', 'judul' => "Lampiran Lampiran PKS No: {$this->pksNomor}", 'raw_text' => $this->generateLampiran()],
        ];
    }

    private function generatePembukaan(): string
    {
        $tanggalSekarang = \Carbon\Carbon::now()->locale('id')->isoFormat('dddd, D MMMM Y');
        $firstParty = $this->leads->nama_perusahaan;
        $secondParty = $this->company->name;
        $pic = $this->tplPicPihakPertama();
        $alamat = $this->tplAlamatPihakPertama();
        $kota = $this->tplKotaPihakPertama();
        $provinsi = $this->tplProvinsiPihakPertama();
        $kebutuhanNama = $this->kebutuhan->nama;
        $direktur = strtoupper($this->company->nama_direktur);

        return <<<HTML
<p class="NoSpacing1" align="center" style="margin-bottom:6.0pt;text-align:center"><b><span lang="EN-US" style="font-size:14.0pt;font-family:"Arial",sans-serif">PERJANJIAN KERJASAMA ALIH DAYA<o:p></o:p></span></b></p>
<p class="NoSpacing1" align="center" style="text-align:center"><b><span lang="EN-US" style="font-size:14.0pt;font-family:"Arial",sans-serif">ANTARA<o:p></o:p></span></b></p>
<p class="NoSpacing1" align="center" style="text-align:center"><b><span lang="EN-US" style="font-size:14.0pt;font-family:"Arial",sans-serif">{$firstParty}<o:p></o:p></span></b></p>
<p class="NoSpacing1" align="center" style="text-align:center"><b><span lang="EN-US" style="font-size:14.0pt;font-family:"Arial",sans-serif">DENGAN<o:p></o:p></span></b></p>
<p class="NoSpacing1" align="center" style="text-align:center"><b><span lang="EN-US" style="font-size:14.0pt;font-family:"Arial",sans-serif">{$secondParty}<o:p></o:p></span></b></p>
<p class="NoSpacing1" align="center" style="text-align:center"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">&nbsp;</span></b></p>
<p class="NoSpacing1" align="center" style="text-align:center"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">No: {$this->pksNomor}</span></b></p>
<p class="MsoNoSpacing" style="text-align:justify;text-justify:inter-ideograph"><b><span lang="IN" style="font-size:12.0pt;font-family:"Arial",sans-serif">Pada Hari ini, {$tanggalSekarang}, telah disepakati Perjanjian Kerjasama Alih Daya:<o:p></o:p></span></b></p>
<p class="NoSpacing1" align="center" style="text-align:center"><b><span lang="IN" style="font-size:12.0pt;font-family:"Arial",sans-serif">Antara:<o:p></o:p></span></b></p>
<p class="MsoNoSpacing" style="margin-left:211.5pt;text-align:justify;text-justify:inter-ideograph;text-indent:-211.5pt"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">{$firstParty}</span></b><span lang="IN" style="font-size:12.0pt;font-family:"Arial",sans-serif"> : Dalam hal ini diwakili oleh </span><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">{$pic}</span></b><span lang="IN" style="font-size:12.0pt;font-family:"Arial",sans-serif"> sebagai</span><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif"> Direktur </span></b><span lang="IN" style="font-size:12.0pt;font-family:"Arial",sans-serif">yang berkedudukan di {$alamat} Kota {$kota} Provinsi {$provinsi} dan bertindak untuk dan atas nama <b>{$firstParty}</b>, untuk selanjutnya dalam perjanjian ini disebut sebagai <b>PIHAK PERTAMA</b>.<o:p></o:p></span></p>
<p class="MsoNoSpacing" align="center" style="text-align:center"><b><span lang="IN" style="font-size:12.0pt;font-family:"Arial",sans-serif">dan<o:p></o:p></span></b></p>
<p class="MsoNoSpacing" style="margin-left:211.5pt;text-align:justify;text-justify:inter-ideograph;text-indent:-211.5pt"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">{$secondParty}</span></b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif"> : Dalam hal ini diwakili oleh </span><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">{$direktur}</span></b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif"> sebagai <b>Direktur</b> yang berkedudukan di Jalan Jatiluhur Raya No. 206E, Kel. Ngesrep, Kec. Banyumanik, Kota Semarang, dan bertindak untuk dan atas nama <b>{$secondParty}</b>, untuk selanjutnya di dalam perjanjian ini disebut sebagai <b>PIHAK KEDUA</b>.</span></p>
<p class="MsoNormal" style="text-align:justify;text-justify:inter-ideograph"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">PIHAK PERTAMA </span></b><span lang="EN-US" style="font-family:"Arial",sans-serif">dan <b>PIHAK KEDUA</b> selanjutnya secara bersama-sama akan disebut sebagai <b>PARA PIHAK</b>.</span></p>
<p class="MsoNormal" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph"><span lang="EN-US" style="font-family:"Arial",sans-serif">Sebelumnya <b>PIHAK PERTAMA</b> dan <b>PIHAK KEDUA</b> menerangkan hal-hal sebagai berikut:</span></p>
<p class="NoSpacing1" style="margin-left:36.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">1)&nbsp;&nbsp;&nbsp; </span></b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">Bahwa <b>PIHAK PERTAMA</b> adalah perseroan terbatas yang bergerak dalam bidang pemberdayaan bisnis UKM dan UMKM serta ruang hiburan, seni, budaya dan pertemuan komunitas kreatif;</span></p>
<p class="NoSpacing1" style="margin-left:36.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">2)&nbsp;&nbsp;&nbsp; </span></b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">Bahwa <b>PIHAK KEDUA</b> adalah badan usaha yang secara hukum diizinkan menjalankan usaha Perusahaan Alih Daya dan sanggup memenuhi kebutuhan <b>PIHAK PERTAMA</b>;</span></p>
<p class="NoSpacing1" style="margin-left:36.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">3)&nbsp;&nbsp;&nbsp; </span></b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">Bahwa <b>PIHAK PERTAMA</b> membutuhkan Jasa {$kebutuhanNama} dan oleh karena itu <b>PIHAK PERTAMA</b> menunjuk <b>PIHAK KEDUA</b>;</span></p>
<p class="NoSpacing1" style="margin-left:36.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">4)&nbsp;&nbsp;&nbsp; </span></b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">Bahwa <b>PIHAK KEDUA</b> dengan ini bersedia untuk melaksanakan penyediaan Jasa {$kebutuhanNama} sesuai yang disepakati dengan <b>PIHAK PERTAMA</b>;</span></p>
<p class="MsoListParagraph" style="margin-bottom:6.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">5)&nbsp;&nbsp;&nbsp; </span></b><span lang="EN-US" style="font-family:"Arial",sans-serif">Bahwa apabila terjadi pergantian perusahaan penyedia jasa alih daya dan jenis pekerjaan masih tetap ada, maka semua Tenaga Kerja yang masih ada akan beralih kepada perusahaan penyedia jasa alih daya selanjutnya dengan berdasarkan hasil evaluasi kinerja Tenaga Kerja yang telah ditetapkan dan disepakati;</span></p>
<p class="MsoListParagraph" style="text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">6)&nbsp;&nbsp;&nbsp; </span></b><span lang="EN-US" style="font-family:"Arial",sans-serif">Bahwa apabila terjadi perubahan terhadap Upah Minimum Kota/Kabupaten (UMK) yang ditetapkan oleh Gubernur melalui PERATURAN GUBERNUR maka PARA PIHAK sepakat untuk musyawarah terlebih dahulu.</span></p>
<p class="NoSpacing1" style="text-align:justify;text-justify:inter-ideograph"><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">Berdasarkan hal-hal tersebut di atas <b>PARA PIHAK</b> sepakat untuk mengadakan Perjanjian dengan ketentuan sebagai berikut:<o:p></o:p></span></p>
HTML;
    }

    private function generatePasal1(): string
    {
        return '<p class="ListParagraph1CxSpFirst" align="center" style="margin-left:0cm;mso-add-space:auto;text-align:center;tab-stops:0cm"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">Pasal 1<o:p></o:p></span></b></p><p class="ListParagraph1CxSpMiddle" align="center" style="margin-left:0cm;mso-add-space:auto;text-align:center;tab-stops:0cm"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">RUANG LINGKUP PEKERJAAN<o:p></o:p></span></b></p><p class="ListParagraph1" style="margin-left:0cm;text-align:justify;text-justify:inter-ideograph;tab-stops:0cm"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">PIHAK PERTAMA </span></b><span lang="EN-US" style="font-family:"Arial",sans-serif">menunjuk<b> PIHAK KEDUA </b>sebagai jasa penyedia dan pengelola Tenaga Kerja alih daya (<i>outsourcing</i>) Jasa ' . $this->kebutuhan->nama . ' untuk <b>PIHAK PERTAMA</b> yang akan ditempatkan dan atas pelaksanaan pekerjaan tersebut <b>PIHAK PERTAMA</b> akan membayarkan <i>Management Fee</i> kepada <b>PIHAK KEDUA</b>.</span></p>';
    }

    private function generatePasal2(): string
    {
        return '<p class="ListParagraph1CxSpFirst" align="center" style="margin-left:0cm;mso-add-space:auto;text-align:center;tab-stops:0cm"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">Pasal 2<o:p></o:p></span></b></p><p class="ListParagraph1CxSpMiddle" align="center" style="margin-left:0cm;mso-add-space:auto;text-align:center;tab-stops:0cm"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">HAK &amp; KEWAJIBAN PARA PIHAK<o:p></o:p></span></b></p><p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">1. KEWAJIBAN PIHAK PERTAMA:<o:p></o:p></span></b></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">a. Memberikan segala informasi terkait dengan pelaksanaan pekerjaan yang tidak terbatas pada syarat-syarat dilaksanakannya pekerjaan termasuk mematuhi segala perintah, instruksi termasuk peraturan dan atau ketentuan yang diberlakukan oleh <b>PIHAK PERTAMA</b>, sepanjang tidak bertentangan dengan isi perjanjian ini, ketertiban kesusilaan,dan atau peraturan dibidang ketenagakerjaan pada pekerja dari <b>PIHAK KEDUA</b>;</span></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">b. Atas Pelaksanaan pekerjaan yang diberikan oleh <b>PIHAK PERTAMA</b> kepada <b>PIHAK KEDUA</b> maka akan diterbitkan <i>invoice</i> pembayaran oleh <b>PIHAK KEDUA</b> dan menjadi kewajiban <b>PIHAK PERTAMA</b> untuk melakukan pembayaran sesuai dengan waktu yang sudah disepakati;</span></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">c. <b>PIHAK PERTAMA</b> berhak meminta/mengajukan penggantian Tenaga Kerja <b>PIHAK KEDUA</b> yang dinilai atau dianggap tidak produktif dalam performa bertugas berdasarkan hasil penilaian dan evaluasi yang ditetapkan pada SOP;</span></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">d. Mematuhi segala peraturan perundang-undangan terkait dengan perjanjian kerjasama alih daya dan peraturan lain terkait ketenagakerjaan yang berlaku.</span></p><p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">2. KEWAJIBAN PIHAK KEDUA:<o:p></o:p></span></b></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">a. Menyediakan Tenaga Kerja berdasarkan permintaan secara tertulis dari <b>PIHAK PERTAMA</b> kepada <b>PIHAK KEDUA</b> yang berisikan surat penunjukan kesepakatan kerjasama, jenis pekerjaan, dan jumlah Tenaga Kerja yang dibutuhkan;</span></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">b. Menjaga kerahasiaan <b>PIHAK PERTAMA</b> tidak terbatas pada semua keterangan, data-data, catatan-catatan yang diperoleh baik langsung maupun tidak langsung, kepada pihak lain tanpa izin tertulis dari <b>PIHAK PERTAMA</b> baik selama berlakunya Perjanjian ini maupun sesudah Perjanjian ini berakhir;</span></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">c. Membebaskan <b>PIHAK PERTAMA</b> dari segala tuntutan ketenagakerjaan dari pekerja <b>PIHAK KEDUA</b> akibat timbulnya dari perjanjian ini;</span></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">d. <b>PIHAK KEDUA</b> akan menugaskan Tenaga Kerja di lokasi <b>PIHAK PERTAMA</b> dengan jadwal kerja yang telah disepakati oleh <b>PARA PIHAK</b>;</span></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">e. Menyelesaikan secara tuntas segala permasalahan yang timbul baik dalam hubungan dengan Tenaga Kerja atau pihak lain terkait dengan pelaksanaan perjanjian ini, termasuk memberikan sanksi secara tegas atas tindakan pelanggaran atau penyelewengan dari Tenaga Kerja <b>PIHAK KEDUA</b> terhadap tata tertib dan segala peraturan yang berlaku di lokasi <b>PIHAK PERTAMA</b>;</span></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">f. Apabila ada Tenaga Kerja yang melakukan pelanggaran indisipliner maupun pelanggaran lain terhadap SOP, maka <b>PIHAK KEDUA</b> wajib melakukan pembinaan dan konseling terhadap Tenaga Kerja, jika tidak terjadi perubahan dan perbaikan pada Tenaga Kerja, maka <b>PIHAK KEDUA</b> wajib melakukan pengajuan pergantian/penarikan Tenaga Kerja, dengan persetujuan <b>PIHAK PERTAMA</b>;</span></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">g. <b>PIHAK KEDUA</b> wajib segera mengirimkan Tenaga Kerja pengganti sementara jika terjadi <i>turn over</i> dalam waktu 1x24 jam untuk memastikan tidak terjadi kekosongan, selanjutnya untuk proses rekrutmen kandidat dan sampai adanya keputusan penerimaan yakni selambat-lambatnya 4 (empat) hari kerja sejak terjadinya <i>turn over</i> dan disepakati oleh <b>PARA PIHAK</b>;</span></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">h. Apabila Tenaga Kerja <b>PIHAK KEDUA</b> melakukan pelanggaran yang mengakibatkan kerugian pada <b>PIHAK PERTAMA</b> baik secara materil maupun immateril, maka akan dilakukan investigasi dan musyawarah mufakat untuk menentukan nilai kerugian yang harus ditanggung oleh <b>PIHAK KEDUA</b> sesuai dengan hasil investigasi dan nilai kesepakatan <b>PARA PIHAK</b>;</span></p><p class="ListParagraph1" style="text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">i. Menghitung dan membayar gaji/upah pokok beserta <i>variable</i> dan pembayaran lainnya (apabila ada) atas setiap Tenaga Kerja yang dikaryakan di <b>PIHAK PERTAMA</b>.</span></p><p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">3. HAK PIHAK PERTAMA:<o:p></o:p></span></b></p><p class="ListParagraph1" style="margin-left:18.0pt;text-align:justify;text-justify:inter-ideograph"><span lang="EN-US" style="font-family:"Arial",sans-serif">Menerima Tenaga Kerja dari <b>PIHAK KEDUA</b> sesuai dengan syarat-syarat kualifikasi, kompetensi, kualitas dan pencapaian hasil yang telah ditentukan oleh <b>PIHAK PERTAMA</b>.</span></p><p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">4. HAK PIHAK KEDUA:<o:p></o:p></span></b></p><p class="ListParagraph1" style="margin-left:18.0pt;text-align:justify;text-justify:inter-ideograph"><span lang="EN-US" style="font-family:"Arial",sans-serif">Menerima pembayaran atau <i>management fee</i> atas pekerjaan yang telah dilaksanakan <b>PIHAK KEDUA</b> dari <b>PIHAK PERTAMA</b> dengan nominal/nilai yang telah disepakati.</span></p>';
    }

    private function generatePasal3(): string
    {
        $thrPenagihan = $this->ruleThr->hari_penagihan_invoice ?? 'H-30';
        $thrPembayaran = $this->ruleThr->hari_pembayaran_invoice ?? 'H-14';
        $thrRilis = $this->ruleThr->hari_rilis_thr ?? 'H-7';

        return <<<HTML
<p class="MsoNoSpacing" align="center" style="text-align:center"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">Pasal 3</span></b></p>
<p class="MsoNoSpacing" align="center" style="text-align:center"><b><span lang="IN" style="font-size:12.0pt;font-family:"Arial",sans-serif">TUNJANGAN HARI RAYA</span></b></p>
<p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">1. PIHAK PERTAMA</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> akan membayarkan Tunjangan Hari Raya Keagamaan selanjutnya disebut <b>THR</b> kepada Tenaga Kerja <b>PIHAK KEDUA</b> yang ditempatkan di <b>PIHAK PERTAMA</b> sesuai dengan ketentuan peraturan yang berlaku;</span></p>
<p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">2.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Bahwa <b>PIHAK KEDUA</b> akan menagihkan komponen THR pada <b>PIHAK PERTAMA</b> dengan perhitungan berdasarkan upah pokok sesuai dengan peraturan menteri Tenaga Kerja (Permenaker) no.6 tahun 2016 tentang tunjangan hari raya keagamaan bagi pekerja/buruh di perusahaan;</span></p>
<p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">3.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> THR Keagamaan pada saat Hari Raya Idul Fitri sebesar 1 (satu) kali gaji kepada Tenaga Kerja yang memiliki masa kerja selama 12 (dua belas) bulan berturut-turut. Apabila masa kerja Tenaga Kerja belum mencapai 1 (satu) tahun namun telah melebihi 1 (satu) bulan maka akan diberikan THR secara Prorata, dengan skema penagihan <i>invoice</i> sesuai tabel dibawah.</span></p>
<div style="display: flex; justify-content: center; align-items: center; width: 100%;"><table style="border-collapse: collapse; width: 70%;"><tr><th style="border: 2px solid black; padding: 10px; text-align: center; background-color: #d9d9d9; font-weight: bold;">No</th><th style="border: 2px solid black; padding: 10px; text-align: center; background-color: #d9d9d9; font-weight: bold;">Schedule Plan</th><th style="border: 2px solid black; padding: 10px; text-align: center; background-color: #d9d9d9; font-weight: bold;">Time</th></tr>
<tr><td style="border: 2px solid black; padding: 10px; text-align: center;">1</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Penagihan <i>Invoice</i> THR</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Ditagihkan H-{$thrPenagihan}</td></tr>
<tr><td style="border: 2px solid black; padding: 10px; text-align: center;">2</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Pembayaran <i>Invoice</i> THR</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Maksimal h-{$thrPembayaran} hari raya</td></tr>
<tr><td style="border: 2px solid black; padding: 10px; text-align: center;">3</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Rilis THR</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Maksimal h-{$thrRilis} hari raya</td></tr></table></div>
HTML;
    }

    private function generatePasal4(): string
    {
        return '<p class="MsoNormal" align="center" style="text-align:center"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">Pasal 4<o:p></o:p></span></b></p><p class="MsoNormal" align="center" style="text-align:center"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">BIAYA DAN PEMBAYARAN<o:p></o:p></span></b></p><p class="NoSpacing1" style="margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">1. BIAYA KONTRAK<o:p></o:p></span></b></p><p class="MsoNormal" style="margin-left:31.5pt;text-align:justify;text-justify:inter-ideograph;text-indent:-13.5pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">a. <b>PIHAK PERTAMA</b> sepakat untuk membayar <b>Biaya Kontrak</b> setiap bulan (menyesuaikan <i>actual invoice</i>) kepada <b>PIHAK KEDUA</b> untuk pekerjaan alih daya ' . $this->kebutuhan->nama . ' yang dikaryakan di tempat <b>PIHAK PERTAMA</b>;</span></p><p class="MsoNormal" style="margin-left:31.7pt;text-align:justify;text-justify:inter-ideograph;text-indent:-13.7pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">b. Biaya kontrak sudah termasuk upah pokok beserta <i>variable breakdown</i> lainnya, seperti tunjangan, premi BPJS Ketenagakerjaan, BPJS Kesehatan, biaya monitoring dan kontrol, biaya provisi seragam, biaya provisi chemical dan tools, ppn 12%, pph -2% dan <i>management fee</i> yang telah disepakati sebesar ' . $this->tplManagementFeePersen() . ' dari nilai invoice.</span></p><p class="NoSpacing1" style="margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">2. <i>INVOICE</i>/PENAGIHAN<o:p></o:p></span></b></p><p class="NoSpacing1" style="margin-left:31.5pt;text-indent:-13.5pt"><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">a. Jadwal Penagihan &amp; Pembayaran</span></p><div style="display: flex; justify-content: center; align-items: center; width: 100%;"><table style="border-collapse: collapse; width: 70%;"><tr><th style="border: 2px solid black; padding: 10px; text-align: center; background-color: #d9d9d9;">No</th><th style="border: 2px solid black; padding: 10px; text-align: center; background-color: #d9d9d9;">Schedule Plan</th><th style="border: 2px solid black; padding: 10px; text-align: center; background-color: #d9d9d9;">Periode</th></tr>
<tr><td style="border: 2px solid black; padding: 10px; text-align: center;">1</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Cut-Off</td><td style="border: 2px solid black; padding: 10px; text-align: center;">' . $this->salaryRule->cutoff . '</td></tr>
<tr><td style="border: 2px solid black; padding: 10px; text-align: center;">2</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Crosscheck Absen</td><td style="border: 2px solid black; padding: 10px; text-align: center;">' . $this->salaryRule->crosscheck_absen . '</td></tr>
<tr><td style="border: 2px solid black; padding: 10px; text-align: center;">3</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Pengiriman <i>Invoice</i></td><td style="border: 2px solid black; padding: 10px; text-align: center;">' . $this->salaryRule->pengiriman_invoice . '</td></tr>
<tr><td style="border: 2px solid black; padding: 10px; text-align: center;">4</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Perkiraan <i>Invoice</i> Diterima Pelanggan</td><td style="border: 2px solid black; padding: 10px; text-align: center;">' . $this->salaryRule->perkiraan_invoice_diterima . '</td></tr>
<tr><td style="border: 2px solid black; padding: 10px; text-align: center;">5</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Pembayaran <i>Invoice</i></td><td style="border: 2px solid black; padding: 10px; text-align: center;">' . $this->salaryRule->pembayaran_invoice . '</td></tr>
<tr><td style="border: 2px solid black; padding: 10px; text-align: center;">6</td><td style="border: 2px solid black; padding: 10px; text-align: center;">Rilis <i>Payroll</i> / Gaji</td><td style="border: 2px solid black; padding: 10px; text-align: center;">' . $this->salaryRule->rilis_payroll . '</td></tr></table></div>
<p class="LO-normal" style="margin-left:31.5pt;text-indent:-13.5pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">b. <b>PIHAK PERTAMA</b> melakukan pembayaran terhitung maksimal 14 hari kalender setelah menerima <i>invoice</i> asli bermaterai dari <b>PIHAK KEDUA</b> melalui transfer bank ke:<br>Bank : <b>MANDIRI</b><br>Cabang : <b>KCP SURABAYA RUNGKUT MEGAH RAYA</b><br>Rekening : <b>1420001290823</b><br>Atas Nama : <b>' . $this->company->name . '</b></span></p>
<p class="LO-normal" style="text-align:justify"><span lang="EN-US" style="font-family:"Arial",sans-serif">Jika tanggal tempo pembayaran jatuh pada hari Sabtu, Minggu atau hari Libur Nasional, maka <b>PIHAK PERTAMA</b> dapat melakukan pembayaran pada hari efektif berikutnya.</span></p>
<p class="LO-normal" style="text-align:justify"><span lang="EN-US" style="font-family:"Arial",sans-serif">Dalam hal terjadi perubahan data rekening, <b>PIHAK KEDUA</b> wajib segera memberitahukan secara tertulis kepada <b>PIHAK PERTAMA</b> sebelum jadwal pembayaran berikutnya.</span></p>';
    }

    private function generatePasal5(): string
    {
        return '<p class="ListParagraph1CxSpFirst" align="center"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">Pasal 5<o:p></o:p></span></b></p><p class="ListParagraph1CxSpMiddle" align="center"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">JAMINAN PIHAK KEDUA<o:p></o:p></span></b></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify"><span lang="EN-US" style="font-family:"Arial",sans-serif">Pekerja yang ditempatkan oleh <b>PIHAK KEDUA</b> telah melalui proses:<o:p></o:p></span></p><p class="ListParagraph1" style="margin-bottom:6.0pt;text-align:justify;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">a. Wawancara dalam proses seleksi dan penerimaan sesuai dengan kualifikasi yang dibutukan;</span></p><p class="ListParagraph1" style="text-align:justify;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif">b. Pemeriksaan dokumen calon Tenaga Kerja/kandidat mencakup identitas diri/CV (termasuk foto), ijazah atau sertifikat pendidikan formal maupun non formal, sertifikat pelatihan, surat referensi/pengalaman kerja, dll.</span></p><p class="ListParagraph1" style="text-align:justify"><span lang="EN-US" style="font-family:"Arial",sans-serif">Bahwa Tenaga Kerja yang ditempatkan pada <b>PIHAK PERTAMA</b> tunduk kepada peraturan <b>PIHAK PERTAMA</b> dan <b>PIHAK KEDUA</b>. Jika terjadi pelanggaran atas peraturan internal <b>PIHAK PERTAMA</b> maka <b>PIHAK PERTAMA</b> wajib memberitahukan kepada <b>PIHAK KEDUA</b> untuk penindakan secara tertulis melalui Surat Peringatan (SP) tahap pertama sampai dengan tahap ketiga beserta pengambilan sanksi tindakan sebagaimana mestinya sesuai dengan SOP &amp; peraturan perundang-undangan yang berlaku.</span></p>';
    }

    private function generatePasal6(): string
    {
        $pasal6 = '<p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">1.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Yang dimaksud dengan <i>force majeure</i> adalah keadaan yang tidak dapat dipenuhinya pelaksanaan Perjanjian oleh <b>PARA PIHAK</b>, karena terjadi suatu peristiwa yang bukan karena kesalahan Para Pihak, peristiwa mana tidak dapat diketahui/tidak dapat diduga sebelumnya dan di luar kemampuan manusia, seperti bencana alam (gempa bumi, angin topan, kebakaran, banjir), huru-hara, perang, pemogokan umum yang bukan kesalahan <b>PARA PIHAK</b>, <i>sabotase</i>, pemberontakan, dan <i>epidemi</i> yang secara keseluruhan ada hubungan langsung dengan penyelesaian pelaksanaan Perjanjian ini;</span></p>
<p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">2.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Apabila terjadi <i>force majeure</i>, maka Pihak yang terkena <i>force majeure</i> harus memberitahukan secara tertulis kepada Pihak yang tidak terkena <i>force majeure</i> selambat-lambatnya 7 (tujuh) hari kalender sejak terjadinya <i>force majeure</i> tersebut disertai bukti-bukti yang sah, selanjutnya Pihak yang tidak terkena <i>force majeure</i> akan menanggapi;</span></p>
<p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">3.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Apabila hal tersebut tidak dilakukan oleh Pihak yang terkena <i>force majeure</i>, maka Pihak yang tidak terkena <i>force majeure</i> menganggap tidak terjadi <i>force majeure</i>;</span></p>
<p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-align:justify;text-justify:inter-ideograph;text-indent:-18.0pt"><span lang="EN-US" style="font-family:"Arial",sans-serif"><b>4.</b> Dalam hal terjadi <i>force majeure</i>, maka pelaksanaan kewajiban masing-masing Pihak akan ditunda berdasarkan kesepakatan <b>PARA PIHAK</b>.</span></p>';
        return $pasal6;
    }

    private function generatePasal7(): string
    {
        return '<p class="ListParagraph1CxSpFirst" align="center"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">Pasal 7<o:p></o:p></span></b></p><p class="ListParagraph1CxSpMiddle" align="center"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">JANGKA WAKTU PERJANJIAN<o:p></o:p></span></b></p><p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">1.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Masa berlakunya Perjanjian ini adalah terhitung dari <b>' . $this->tplKontrakAwal() . ' sampai dengan ' . $this->tplKontrakAkhir() . '</b> dan dapat ditinjau kembali oleh <b>PARA PIHAK</b>;</span></p><p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">2.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Sebelum perjanjian ini berakhir <b>PARA PIHAK</b> akan memberitahukan secara tertulis maksud untuk memperpanjang atau tidak memperpanjang Perjanjian ini 30 (tiga puluh) hari sebelum berakhirnya perjanjian ini;</span></p><p class="ListParagraph1" style="margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">3.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Apabila <b>PARA PIHAK</b> tidak memberitahukan hal tersebut maka secara otomatis perjanjian ini diperpanjang dengan mendasarkan pada ketentuan Upah Minimum Kabupaten/Kota yang berlaku.</span></p>';
    }

    private function generatePasal8(): string
    {
        return '<p class="ListParagraph1CxSpFirst" align="center"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">Pasal 8<o:p></o:p></span></b></p><p class="ListParagraph1CxSpMiddle" align="center"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">PENYELESAIAN PERSELISIHAN<o:p></o:p></span></b></p><p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">1.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Apabila dikemudian hari terjadi perselisihan atau permasalahan antara kedua belah pihak, sehubungan dengan pelaksanaan dan penafsiran perjanjian ini, maka <b>PARA PIHAK</b> setuju untuk menyelesaikan permasalahan atau perselisihan dengan musyawarah untuk mufakat;</span></p><p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">2.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Apabila cara penyelesaian musyawarah tersebut di atas gagal untuk mencapai kata mufakat, maka <b>PARA PIHAK</b> setuju menunjuk Kantor Panitera Pengadilan Negeri Surabaya untuk lembaga penyelesaian sengketa;</span></p><p class="ListParagraph1" style="margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">3.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Selama masa penyelesaian sengketa di pengadilan, <b>PARA PIHAK</b> tetap diwajibkan untuk menjalankan masing-masing kewajibannya.</span></p>';
    }

    private function generatePasal9(): string
    {
        return '<p class="ListParagraph1CxSpFirst" align="center"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">Pasal 9<o:p></o:p></span></b></p><p class="ListParagraph1CxSpMiddle" align="center"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">PENUTUP<o:p></o:p></span></b></p><p class="ListParagraph1" style="margin-top:0cm;margin-right:0cm;margin-bottom:6.0pt;margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">1.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Apabila terdapat perubahan, tambahan dan atau hal-hal lain yang belum cukup diatur dalam Perjanjian ini, maka akan dibuat secara tertulis dan ditanda tangani oleh kedua belah pihak dan merupakan bagian yang tidak terpisahkan dari Perjanjian ini;</span></p><p class="ListParagraph1" style="margin-left:18.0pt;text-indent:-18.0pt"><b><span lang="EN-US" style="font-family:"Arial",sans-serif">2.</span></b><span lang="EN-US" style="font-family:"Arial",sans-serif"> Perjanjian ini dibuat rangkap dua (2), masing-masing bermaterai cukup dan memiliki kekuatan hukum yang sama dan berlaku sejak ditandatangani oleh kedua belah pihak.</span></p><p class="MsoNoSpacing">&nbsp;</p><table class="MsoNormalTable" border="1" cellspacing="0" cellpadding="0" width="618" style="border:none;"><tr><td width="390" valign="top"><p class="NoSpacing1"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">PIHAK PERTAMA<o:p></o:p></span></b></p><p class="NoSpacing1"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">' . $this->leads->nama_perusahaan . '<o:p></o:p></span></b></p><p class="NoSpacing1"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif"><u>' . strtoupper($this->leads->pic) . '</u><o:p></o:p></span></b></p><p class="NoSpacing1"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">Direktur<o:p></o:p></span></b></p></td><td width="228" valign="top"><p class="NoSpacing1"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">PIHAK KEDUA<o:p></o:p></span></b></p><p class="NoSpacing1"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">' . $this->company->name . '<o:p></o:p></span></b></p><p class="NoSpacing1"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif"><u>' . strtoupper($this->company->nama_direktur) . '</u><o:p></o:p></span></b></p><p class="NoSpacing1"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">Direktur<o:p></o:p></span></b></p></td></tr></table>';
    }

    private function generateLampiran(): string
    {
        return '<p class="NoSpacing1"><b><span lang="EN-US" style="font-size:12.0pt;font-family:"Arial",sans-serif">Lampiran PKS No: ' . $this->pksNomor . '</span></b></p>';
    }
}
